class Node:
    def __init__(self, label, screenshot_path=None, layout_path=None, apk_pkg_name=None, activity=None):
        self.label = label
        self.layout_helper = None
        self.hash_id = None
        self.pkg_name = apk_pkg_name
        if layout_path is not None and exists(layout_path):
            self.layout_helper = Layout(layout_path)
            self.hash_id = self.layout_helper.get_layout_hash(self.pkg_name)
        self.activity = activity

    def set_activity(self, activity):
        self.activity = activity

    def __str__(self):
        return self.label

    def __hash__(self):
        return self.hash_id

    def __eq__(self, other):
        return self.__hash__() == other.__hash__()

    def to_dict(self):
        return {
            "label": self.label,
            "pkg_name": self.pkg_name,
            "activity": self.activity,
            "hash_id": self.__hash__()
        }

    @staticmethod
    def from_dict(body):
        node = Node(label=body['label'], apk_pkg_name=body['pkg_name'], activity=body['activity'])
        node.hash_id = body['hash_id']
        return node

    def to_neo4j_attr_str(self, app_id, entry_node_id):
        attr_str = ",".join([k + ':\"' + str(v) + '\"' for k, v in self.to_dict().items()])
        label = app_id.replace("-", "_")
        if entry_node_id == self.label:
            label += ":EntryState"
        return f"(:{label} {{{attr_str}}})"


