class Edge:
    matched_by = None

    def __init__(self, src: str, tgt: str, event: Event, id:str=None):
        self.src = src
        self.tgt = tgt
        self.event = event
        self.id = str(id)

    def __str__(self):
        return f"{self.src}, {self.tgt}, {self.event.__str__()}"

    def __hash__(self):
        return int(hashlib.md5(self.__str__().encode()).hexdigest(), 16)

    def set_id(self, inx):
        self.id = str(inx)

    def set_is_matched_by(self, step_idx):
        self.matched_by = step_idx

    def get_is_matched_by(self):
        return f"Match with step: {self.matched_by}" if self.matched_by is not None else ""

    def is_matched(self):
        return self.matched_by is not None

    def __eq__(self, other):
        return self.__hash__() == other.__hash__()

    def to_dict(self):
        return {
            "id": self.id,
            "src": self.src,
            "tgt": self.tgt,
            **self.event.to_dict()
        }

    @staticmethod
    def from_dict(body):
        # call the corresponding static method to restore event object
        event_json_to_obj = {
            "SWIPE": SwipeEvent.from_dict,
            "SCROLL": ScrollEvent.from_dict,
            "ROTATE": RotateEvent.from_dict,
            "BACK": BackEvent.from_dict,
            "INPUT": InputEvent.from_dict,
            "CLICK": ClickEvent.from_dict,
            "LONG_CLICK": LongClickEvent.from_dict
        }
        event_obj = event_json_to_obj[body['action']](body)
        # restore edge object
        return Edge(body['src'], body['tgt'], event_obj, body['id'])

    def to_neo4j_attr_str(self):
        attr_str = ",".join([
            k + ':\"' + str(v) + '\"' if not isinstance(v, List) else k + ':' + json.dumps(v).lstrip("\"").rstrip("\"")
            for k, v in self.to_dict().items()
        ])
        return f"[:{self.to_dict()['action']} {{{attr_str}}}]"


class GUIModel:
    logger = get_logger("gui-model")
    neo4j_driver = None

    def __init__(self, app_id, entry_node_id=None, nodes: Dict[str, Node] = None, edges: Dict[str, Edge] = None, output_dir=None, treat_input_as_click = False, only_check_existance = False):
        """
        Parameter app_id: the id of the current app
        Parameter entry_node_id, nodes, edges: the parameters to specify raw information of the model which will be stored in Neo4j, need to be passed in the first time constructing the model;
        Parameter output_dir: the directory to store all the computed information of nodes and edges. If the directory is none, the all the computed information will just be for one-time use.
        Parameter treat_input_as_click: if set as True, when loading the GUI model, we generate a dummy Click event for all Input events.
        """
        self.logger.info(f"Constructing GUI model for {app_id}")
        self.app_id = app_id.replace("-", "_")
        self.nodes = nodes
        self.edges = edges
        self.entry_node_id = entry_node_id
        self.treat_input_as_click = treat_input_as_click
        try:
            self.neo4j_driver = connect_neo4j(Neo4JConfg.ip, Neo4JConfg.username, Neo4JConfg.password)
        except ServiceUnavailable as e: # switching host name for connecting to Neo4j db in docker container
            self.neo4j_driver = connect_neo4j("bolt://neo4j:7687", Neo4JConfg.username, Neo4JConfg.password)

        if entry_node_id is not None and nodes is not None and edges is not None:
            # the first time initialize the graph, dump it to neo4j
            self.__to_neo4j(entry_node_id, nodes, edges)
        else:
            # the model is supposed to be in neo4j already, check its existence
            self.check_model_existence()

        if only_check_existance:
             return 

        # construct the shortest path between nodes (this information will be used to determine the node reachability info and edge info); If an output_dir is provided, then try to load pre-computed results from the directory and dump the newly computed information into it.
        self.shortest_paths_between_nodes = dict()
        self.__init_nodes_shortest_paths(output_dir)

        # construct the edges' information: reachability (forward and backward), NOTE: has to be called after initing nodes
        self.edges_reachable = dict()  # edge_idx -> list of indexes of edges that are reachable from the key edge
        self.edges_backward_reachable = dict()  # edge_idx -> list of indexes of edges that can reach the key edge
        self.__init_edges_reachability(output_dir)

    def get_all_nodes(self) -> Dict[str, Node]:
        neo4j_query = f"MATCH (p:{self.app_id}) RETURN p"
        if self.nodes is None:
            results = execute_neo4j_query(self.neo4j_driver, neo4j_query, Neo4JConfg.db_name)
            nodes = [Node.from_dict(dict(i.get('p').items())) for i in results]
            self.nodes = dict([(i.label, i) for i in nodes])
        return self.nodes

    def get_all_edges(self) -> Dict[str, Edge]:
        neo4j_query = f"MATCH (a:{self.app_id})-[t]->(b:{self.app_id}) RETURN t"
        if self.edges is None:
            results = execute_neo4j_query(self.neo4j_driver, neo4j_query, Neo4JConfg.db_name)
            edges = [Edge.from_dict(dict(i.get('t').items())) for i in results]
            if self.treat_input_as_click:
                self.__add_dumpy_click_events_for_input_events(edges)
            self.edges = dict([(i.id, i) for i in edges])
        return self.edges

    def __add_dumpy_click_events_for_input_events(self, edges:List[Edge]):
        input_edges = [edge for edge in edges if isinstance(edge.event, InputEvent)]
        for input_edge in input_edges:
            new_click_event = ClickEvent.from_dict(input_edge.event.to_dict())
            new_click_event.text_representation.append("input box") 
            # the ad-hoc id of edge for clicking an input box is the id of the corresponding input edge plus the total number of edges
            edges.append(Edge(input_edge.src, input_edge.tgt, new_click_event, str(int(input_edge.id) + len(edges)))) 
            new_long_click_event = LongClickEvent.from_dict(input_edge.event.to_dict())
            new_long_click_event.text_representation.append("input box")
            # the ad-hoc id of edge for long-clicking an input box is the id of the corresponding input edge plus two times the total number of edges
            edges.append(Edge(input_edge.src, input_edge.tgt, new_long_click_event, str(int(input_edge.id) + 2*len(edges))))         

    def get_entry_node_label(self):
        neo4j_query = f"MATCH (a:{self.app_id}:EntryState) RETURN a.label"
        if self.entry_node_id is None:
            results = execute_neo4j_query(self.neo4j_driver, neo4j_query, Neo4JConfg.db_name)
            self.entry_node_id = results[0].get('a.label')
        return self.entry_node_id

    def __init_nodes_shortest_paths(self, output_dir: Optional[str]):
        shortest_paths_file_path = join(str(output_dir), 'shortest_paths.json')
        if exists(shortest_paths_file_path):
            self.logger.debug("Loading the shortest paths between nodes...")
            self.shortest_paths_between_nodes = load_json_file(shortest_paths_file_path)
            return
        # computing nodes information
        self.logger.debug("Initializing the shortest paths between nodes...")
        for src_node_id in self.get_all_nodes():
            self.shortest_paths_between_nodes[src_node_id] = dict()
            for tgt_node_id in self.get_all_nodes():
                try:
                    shortest_paths = self.__query_shortest_paths_between_nodes(src_node_id, tgt_node_id)
                    self.shortest_paths_between_nodes[src_node_id][tgt_node_id] = shortest_paths
                except NodesNotReachable:
                    self.shortest_paths_between_nodes[src_node_id][tgt_node_id] = None
        if output_dir is not None:
            dump_json_file(shortest_paths_file_path, self.shortest_paths_between_nodes)
        self.logger.debug("Done...")

    def __init_edges_reachability(self, output_dir:Optional[str]):
        edge_reachability_file_path= join(str(output_dir), 'edge_reachability.json')
        edge_backward_reachability_file_path = join(str(output_dir), 'edge_backward_reachability.json')

        if exists(edge_reachability_file_path) and exists(edge_backward_reachability_file_path):
            self.logger.debug("Loading edge reachability information...")
            self.edges_reachable = load_json_file(edge_reachability_file_path)
            self.edges_backward_reachable = load_json_file(edge_backward_reachability_file_path)
            return
        else:
            self.logger.debug("Initializing edge reachability information...")
            for src_edge_idx in self.get_all_edges():
                self.edges_reachable[src_edge_idx] = set()
                for tgt_edge_idx in self.get_all_edges():
                    if tgt_edge_idx not in self.edges_backward_reachable:
                        self.edges_backward_reachable[tgt_edge_idx] = set()
                    edge_a = self.get_all_edges()[src_edge_idx]
                    edge_b = self.get_all_edges()[tgt_edge_idx]
                    reachable = self.node_is_reachable(edge_a.tgt, edge_b.src)
                    if reachable:
                        self.edges_reachable[src_edge_idx].add(tgt_edge_idx)
                        self.edges_backward_reachable[tgt_edge_idx].add(src_edge_idx)
            self.logger.debug("Done...")
        # needs to transform the sets into list for storing
        for edge_idx in self.get_all_edges():
            self.edges_reachable[edge_idx] = list(self.edges_reachable[edge_idx])
            self.edges_backward_reachable[edge_idx] = list(self.edges_backward_reachable[edge_idx])
        if output_dir is not None:
            dump_json_file(edge_reachability_file_path, self.edges_reachable)
            dump_json_file(edge_backward_reachability_file_path, self.edges_backward_reachable)

    def __query_shortest_paths_between_nodes(self, start_state_id, end_state_id) -> List[List[str]]:
        """ Query the shortest paths between two nodes.

        Args:
            start_state_id (_type_): the id of the starting state
            end_state_id (_type_): the id of the ending state

        Raises:
            NodesNotReachable: if the queried two nodes are not reachable, this exception will be thrown

        Returns:
            List[List[str]]: A list of paths. Each path is a list of edge ids.
        """
        neo4j_query = f'MATCH p=allShortestPaths((a:{self.app_id})-[*0..]->(b:{self.app_id})) WHERE a.label = \"{start_state_id}\" AND b.label = \"{end_state_id}\" RETURN p;'
        results = execute_neo4j_query(self.neo4j_driver, neo4j_query, Neo4JConfg.db_name)
        # two nodes are not reachable
        if len(results) == 0:
            raise NodesNotReachable()
        shortest_paths = [
            [
                Edge.from_dict(dict(i.items())).id 
                for i in result.get('p').relationships
            ]
            for result in results
        ]
        return shortest_paths

    def query_paths_in_length_from_node(self, src_node_id, length, strict_length=False) -> List[List[Edge]]:
        neo4j_query = f"MATCH (a:{self.app_id} {{label:\"{src_node_id}\"}} )-[p*{'' if strict_length else '..'}{length}]->(b) RETURN p"
        results = execute_neo4j_query(self.neo4j_driver, neo4j_query, Neo4JConfg.db_name)
        # two nodes are not reachable
        if len(results) == 0:
            return []
        paths = [
            [
                Edge.from_dict(dict(i.items())) for i in result.get('p')
            ]
            for result in results
        ]
        return paths

    def node_is_reachable(self, src_node_id: str, tgt_node_id: str):
        assert src_node_id in self.shortest_paths_between_nodes and tgt_node_id in self.shortest_paths_between_nodes[src_node_id]
        return self.shortest_paths_between_nodes[src_node_id][tgt_node_id] is not None

    def edge_is_reachable(self, edge_a_id, edge_b_id):
        return edge_b_id in self.edges_reachable[edge_a_id]

    def edge_reachable_from_entry(self, edge_idx):
        src_node = self.get_entry_node_label()
        tgt_node = self.get_all_edges()[edge_idx].src
        return self.node_is_reachable(src_node, tgt_node)

    def get_edges_reachable_from_edge(self, edge_idx) -> list[str]:
        return self.edges_reachable[edge_idx]

    def get_edges_reach_edge(self,edge_idx) -> list[str]:
        return self.edges_backward_reachable[edge_idx]

    def get_shortest_paths_between_nodes(self, src_state_id, tgt_state_id)->List[List[Edge]]:
        assert src_state_id in self.shortest_paths_between_nodes and tgt_state_id in self.shortest_paths_between_nodes[src_state_id], f"Error: the shortest path between node {src_state_id} and node {tgt_state_id} is not computed."
        if self.shortest_paths_between_nodes[src_state_id][tgt_state_id] is None:
            raise NodesNotReachable(f"node {src_state_id} and node {tgt_state_id} are not reachable")
        else:
            return [
                [
                    self.get_all_edges()[edge_id]
                    for edge_id in path
                ] 
                for path in self.shortest_paths_between_nodes[src_state_id][tgt_state_id]
            ]

